DROP TABLE IF EXISTS `po_receipt_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `po_receipt_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `receipt_id` int NOT NULL,
  `po_item_id` int DEFAULT NULL,
  `received_quantity` decimal(12,3) DEFAULT '0.000',
  `received_weight` decimal(12,3) DEFAULT '0.000',
  `length` decimal(12,4) DEFAULT '0.0000',
  `width` decimal(12,4) DEFAULT '0.0000',
  `thickness` decimal(12,4) DEFAULT '0.0000',
  `diameter` decimal(12,4) DEFAULT '0.0000',
  `outer_diameter` decimal(12,4) DEFAULT '0.0000',
  `density` decimal(12,4) DEFAULT '0.0000',
  `weight_per_unit` decimal(12,4) DEFAULT '0.0000',
  `item_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `material_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drawing_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `po_qty` decimal(12,3) DEFAULT '0.000',
  PRIMARY KEY (`id`),
  KEY `receipt_id` (`receipt_id`),
  CONSTRAINT `po_receipt_items_ibfk_1` FOREIGN KEY (`receipt_id`) REFERENCES `po_receipts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
