--
-- Table structure for table `purchase_orders`
--

DROP TABLE IF EXISTS `purchase_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchase_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `po_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `quotation_id` int DEFAULT NULL,
  `vendor_id` int DEFAULT NULL,
  `sales_order_id` int DEFAULT NULL,
  `status` enum('DRAFT','PO_REQUEST','ORDERED','SENT','ACKNOWLEDGED','RECEIVED','PARTIALLY_RECEIVED','CLOSED','COMPLETED','FULFILLED','APPROVED','PENDING_PAYMENT','PAID','MERGED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ORDERED',
  `total_amount` decimal(14,2) DEFAULT '0.00',
  `expected_delivery_date` date DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `store_acceptance_status` enum('PENDING','ACCEPTED','REJECTED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING',
  `store_acceptance_date` timestamp NULL DEFAULT NULL,
  `store_acceptance_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `mr_id` int DEFAULT NULL,
  `approved_by` int DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `invoice_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `public_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `merged_into_po_id` int DEFAULT NULL,
  `is_merged` tinyint(1) NOT NULL DEFAULT '0',
  `forwarded_to_accounts` tinyint DEFAULT '0',
  `discount_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'AMOUNT',
  `discount_value` decimal(14,2) DEFAULT '0.00',
  `discount_amount` decimal(14,2) DEFAULT '0.00',
  PRIMARY KEY (`id`),
  UNIQUE KEY `po_number` (`po_number`),
  UNIQUE KEY `public_id` (`public_id`),
  KEY `idx_quotation_id` (`quotation_id`),
  KEY `idx_status` (`status`),
  KEY `idx_vendor_id` (`vendor_id`),
  KEY `sales_order_id` (`sales_order_id`),
  KEY `fk_merged_into_po` (`merged_into_po_id`),
  CONSTRAINT `fk_merged_into_po` FOREIGN KEY (`merged_into_po_id`) REFERENCES `purchase_orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `purchase_orders_ibfk_1` FOREIGN KEY (`quotation_id`) REFERENCES `quotations` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `purchase_orders_ibfk_2` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `purchase_orders_ibfk_3` FOREIGN KEY (`sales_order_id`) REFERENCES `sales_orders` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=477 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

