--
-- Table structure for table `quotations`
--

DROP TABLE IF EXISTS `quotations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quotations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `quote_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sales_order_id` int DEFAULT NULL,
  `mr_id` int DEFAULT NULL,
  `vendor_id` int NOT NULL,
  `status` enum('DRAFT','SENT','RECEIVED','REVIEWED','CLOSED','PENDING','EMAIL_RECEIVED','SUPERSEDED','REJECTED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT',
  `valid_until` date DEFAULT NULL,
  `total_amount` decimal(14,2) DEFAULT '0.00',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `received_pdf_path` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `tax_amount` decimal(14,2) DEFAULT '0.00',
  `grand_total` decimal(14,2) DEFAULT '0.00',
  `rfq_id` int DEFAULT NULL,
  `rfq_group_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int DEFAULT '1',
  `base_quote_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `host_company_id` int DEFAULT NULL,
  `gst_percentage` decimal(10,2) DEFAULT '18.00',
  PRIMARY KEY (`id`),
  UNIQUE KEY `base_quote_version` (`base_quote_number`,`version`),
  KEY `fk_quotations_mr` (`mr_id`),
  KEY `idx_rfq_group_id` (`rfq_group_id`),
  KEY `idx_sales_order_id` (`sales_order_id`),
  KEY `idx_status` (`status`),
  KEY `idx_vendor_id` (`vendor_id`),
  KEY `rfq_id` (`rfq_id`),
  CONSTRAINT `fk_quotations_mr` FOREIGN KEY (`mr_id`) REFERENCES `material_requests` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quotations_ibfk_1` FOREIGN KEY (`sales_order_id`) REFERENCES `sales_orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quotations_ibfk_2` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE CASCADE,
  CONSTRAINT `quotations_ibfk_3` FOREIGN KEY (`rfq_id`) REFERENCES `procurement_rfqs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quotations_ibfk_4` FOREIGN KEY (`rfq_id`) REFERENCES `procurement_rfqs` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=650 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

