--
-- Table structure for table `sales_orders`
--

DROP TABLE IF EXISTS `sales_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `customer_po_id` int DEFAULT NULL,
  `so_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `net_total` decimal(14,2) DEFAULT '0.00',
  `company_id` int NOT NULL,
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drawing_required` tinyint(1) DEFAULT '0',
  `production_priority` enum('LOW','NORMAL','HIGH') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'NORMAL',
  `target_dispatch_date` date DEFAULT NULL,
  `status` enum('CREATED','DESIGN_IN_REVIEW','DESIGN_APPROVED','DESIGN_QUERY','QUOTATION_SENT','BOM_SUBMITTED','BOM_APPROVED','PROCUREMENT_IN_PROGRESS','MATERIAL_PURCHASE_IN_PROGRESS','MATERIAL_READY','IN_PRODUCTION','PRODUCTION_COMPLETED','QC_IN_PROGRESS','QC_APPROVED','QC_REJECTED','READY_FOR_SHIPMENT','SHIPPED','CLOSED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'CREATED',
  `current_department` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'SALES',
  `request_accepted` tinyint(1) DEFAULT '0',
  `bom_id` int DEFAULT NULL,
  `cgst_rate` decimal(5,2) DEFAULT '0.00',
  `sgst_rate` decimal(5,2) DEFAULT '0.00',
  `profit_margin` decimal(14,2) DEFAULT '0.00',
  `material_available` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `quotation_id` int DEFAULT NULL,
  `source_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'DIRECT',
  `is_sales_order` tinyint(1) DEFAULT '0',
  `billing_address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `shipping_address` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gstin` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `excel_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `zip_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_id` int DEFAULT NULL,
  `public_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `host_company_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `public_id` (`public_id`),
  KEY `company_id` (`company_id`),
  KEY `customer_po_id` (`customer_po_id`),
  KEY `idx_current_department` (`current_department`),
  KEY `idx_status` (`status`),
  CONSTRAINT `sales_orders_ibfk_1` FOREIGN KEY (`customer_po_id`) REFERENCES `customer_pos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sales_orders_ibfk_2` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=422 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sales_orders`
--

