--
-- Table structure for table `stock_ledger`
--

DROP TABLE IF EXISTS `stock_ledger`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stock_ledger` (
  `id` int NOT NULL AUTO_INCREMENT,
  `item_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `transaction_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `transaction_type` enum('IN','OUT','ADJUSTMENT','RETURN','GRN_IN') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` decimal(12,3) NOT NULL,
  `reference_doc_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reference_doc_id` int DEFAULT NULL,
  `reference_doc_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qc_id` int DEFAULT NULL,
  `grn_item_id` int DEFAULT NULL,
  `balance_after` decimal(12,3) DEFAULT NULL,
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `created_by` int DEFAULT NULL,
  `material_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `material_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `valuation_rate` decimal(12,2) DEFAULT '0.00',
  `selling_rate` decimal(12,2) DEFAULT '0.00',
  `no_of_cavity` int DEFAULT '1',
  `weight_per_unit` decimal(12,3) DEFAULT '0.000',
  `weight_uom` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drawing_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `revision` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `material_grade` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Nos',
  `drawing_id` int DEFAULT NULL,
  `product_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `warehouse` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qty_in` decimal(12,3) DEFAULT '0.000',
  `qty_out` decimal(12,3) DEFAULT '0.000',
  `public_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hsn_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `min_stock` decimal(12,3) DEFAULT '10.000',
  `max_stock` decimal(12,3) DEFAULT '500.000',
  `reorder_level` decimal(12,3) DEFAULT '20.000',
  `weight_in` decimal(15,3) NOT NULL DEFAULT '0.000',
  `weight_out` decimal(15,3) NOT NULL DEFAULT '0.000',
  `weight_after` decimal(15,3) NOT NULL DEFAULT '0.000',
  `length` decimal(12,4) DEFAULT NULL,
  `width` decimal(12,4) DEFAULT NULL,
  `thickness` decimal(12,4) DEFAULT NULL,
  `diameter` decimal(12,4) DEFAULT NULL,
  `outer_diameter` decimal(12,4) DEFAULT NULL,
  `density` decimal(10,4) DEFAULT NULL,
  `shape_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_grn_ledger` (`reference_doc_id`,`grn_item_id`,`transaction_type`),
  UNIQUE KEY `public_id` (`public_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_item_code` (`item_code`),
  KEY `idx_qc_id` (`qc_id`),
  KEY `idx_transaction_date` (`transaction_date`),
  KEY `idx_transaction_type` (`transaction_type`),
  CONSTRAINT `stock_ledger_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=605 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

